package com.nexusdrive.metadata.controller;import com.nexusdrive.common.dto.ApiResponse;import com.nexusdrive.common.security.CustomUserDetails;import com.nexusdrive.metadata.dto.*;import com.nexusdrive.metadata.service.FolderService;import io.swagger.v3.oas.annotations.Operation;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/folders")public class FolderController{private final FolderService folders;public FolderController(FolderService f){folders=f;}@Operation(summary="Create folder")@PostMapping@PreAuthorize("hasAnyRole('ADMIN','USER')")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<FolderResponse> create(@AuthenticationPrincipal CustomUserDetails u,@Valid@RequestBody FolderRequest r){return ApiResponse.ok(FolderResponse.from(folders.create(u.userId(),r)));}@Operation(summary="Rename or move folder")@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','USER')")public ApiResponse<FolderResponse> update(@AuthenticationPrincipal CustomUserDetails u,@PathVariable UUID id,@Valid@RequestBody FolderRequest r){return ApiResponse.ok(FolderResponse.from(folders.update(u.userId(),id,r)));}@Operation(summary="Delete folder")@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','USER')")public ApiResponse<Void> delete(@AuthenticationPrincipal CustomUserDetails u,@PathVariable UUID id){folders.delete(u.userId(),id);return ApiResponse.ok(null);}@Operation(summary="List folder contents")@GetMapping("/{id}/contents")public ApiResponse<FolderContentsResponse> contents(@AuthenticationPrincipal CustomUserDetails u,@PathVariable UUID id){return ApiResponse.ok(folders.contents(u.userId(),id));}}
